/* Фикстура стабильности block-id: изменение строк ВЫШЕ не должно менять id.
   ВАЖНО: не менять структуру ниже — тест зависит от порядка блоков. */
static int stability_fn(void) {
  for (int i = 0; i < 10; i++) {
    if (i > 3) {
      i += 2;
    }
    if (i < 7) {
      i += 1;
    }
  }
  return 0;
}